from pathlib import Path

p = Path('src/services/two_report_pdf.py')
s = p.read_text(encoding='utf-8')
s = s.replace('from pathlib import Path', 'from pathlib import Path\nimport unicodedata')
s = s.replace("if any('\\u0900' <= char <= '\\u097f' for char in text):", "if any(char.isalpha() and 'LATIN' not in unicodedata.name(char, '') for char in text):")
s = s.replace('textColor=colors.HexColor("#234E52"), spaceBefore=8, spaceAfter=4)', 'textColor=colors.HexColor("#234E52"), backColor=colors.HexColor("#E7F1ED"), borderPadding=4, spaceBefore=8, spaceAfter=5)')
s = s.replace('str(value) if value not in (None, "") else "Not provided"', 'str(value) if value not in (None, "") else "Not provided"')
s = s.replace('f"{key}: {item}"', 'f"{key}: {self._list(item)}"')
s = s.replace('canvas.drawRightString(A4[0]-12*mm, 7*mm, f"Page {doc.page}")', 'canvas.drawString(12*mm, A4[1]-8*mm, doc.title); canvas.drawRightString(A4[0]-12*mm, 7*mm, f"Page {doc.page}")')
s = s.replace('self._p("Report status"), self._p(status)', 'self._p("Report status"), self._p(status)')
s = s.replace('for k in ("name", "age", "gender", "goal", "dietary_preference", "allergies", "food_intolerances", "foods_to_avoid", "health_conditions")', 'for k in ("name", "age", "gender", "goal", "main_complaint", "health_conditions")')
s = s.replace('"3. Food Preferences Allergies and Restrictions"', '"4. Food Preferences, Allergies and Restrictions"')
s = s.replace('"4. Personalized Nutrition Analysis"', '"3. Personalized Nutrition Analysis"')
s = s.replace('"14. References and Educational Disclaimer"', '"14. References / Evidence"')
s = s.replace('"15. Doctor Approval and Signature"', '"16. Doctor Approval and Signature"')
s = s.replace('Paragraph("16. Doctor Approval and Signature", self.section)', 'Paragraph("15. Educational Disclaimer", self.section), self._p("Traditional Ayurvedic wellness education is not a diagnosis, prescription, disease treatment, cure, prevention promise or guarantee. Follow the reviewing doctor instructions and seek qualified care for severe symptoms."), Paragraph("16. Doctor Approval and Signature", self.section)')
s = s.replace('self._p("Safety"), self._p(item.get("safety_consideration"))', 'self._p("Safety / wellness basis"), self._p(self._list(item.get("safety_consideration")) + " | " + self._list(item.get("wellness_basis")))')
s = s.replace("f\"Session {state['session_id']} | Approved version", "f\"Report {state['final_report_id']} | Session {state['session_id']} | Approved version")
s = s.replace('        story += [Paragraph("Doctor Final Comments", self.section), self._p(doctor.get("final_comments"))]', '''        story += [Paragraph("Doctor Final Comments", self.section), self._p(doctor.get("final_comments")), self._p("Doctor contact: " + self._list(doctor.get("contact_information")))]''')
s = s.replace('"6. AI Assessment Status"', '"10. AI Assessment Status"').replace('"7. Safety Disclaimer"', '"11. Safety Disclaimer"').replace('"5. Assessment Limitations"', '"9. Assessment Limitations"').replace('"4. SYMPTOM-BASED DISEASE SCREENING"', '"7. SYMPTOM-BASED DISEASE SCREENING"')
s = s.replace('story.append(Paragraph("3. Preliminary Ayurvedic Assessment", self.section))', 'story.append(Paragraph("3. Prakriti, 4. Vikriti and 5. Agni / Digestion Assessments", self.section))')
s = s.replace('story.append(self._table(rows, [37*mm, 72*mm, 77*mm]))', 'story.append(self._table(rows, [37*mm, 72*mm, 77*mm]))\n        story += [Paragraph("8. Assessment Scoring Summary", self.section), self._p("The recorded assessment scores are shown alongside each result above. Missing or inconsistent source answers require doctor review.")]')
p.write_text(s, encoding='utf-8')
